import zipfile
import re
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

path = 'budget.xlsx'
with zipfile.ZipFile(path) as z:
    names = z.namelist()
    print("Archive entries:")
    for n in names:
        print(" ", n)

    shared = []
    if 'xl/sharedStrings.xml' in names:
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared.append(text)

    sheet_files = sorted(
        (n, m) for n, m in
        ((n, re.match(r'xl/worksheets/sheet(\d+)\.xml', n)) for n in names)
        if m
    )

    def col_to_idx(ref):
        col = re.match(r'[A-Z]+', ref).group(0)
        idx = 0
        for ch in col:
            idx = idx * 26 + (ord(ch) - ord('A') + 1)
        return idx - 1

    for fname, _ in sheet_files:
        print(f"\n=== {fname} ===")
        root = ET.fromstring(z.read(fname))
        sheet_data = root.find('m:sheetData', NS)
        rows = []
        for row in sheet_data.findall('m:row', NS):
            cells = {}
            for c in row.findall('m:c', NS):
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                isel = c.find('m:is', NS)
                if v is not None:
                    val = v.text
                elif isel is not None:
                    val = ''.join(t.text or '' for t in isel.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
                else:
                    val = ''
                if t == 's' and v is not None:
                    val = shared[int(val)]
                cells[col_to_idx(ref)] = val
            if cells:
                rows.append(cells)
        maxcol = max((max(r) for r in rows), default=-1)
        for r in rows:
            line = ' | '.join(r.get(i, '') for i in range(maxcol + 1))
            print(line)

